function renderStatistics(){const months=new Map();for(const r of analyticsRows()){const key=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit'}).format(new Date(r.start));const m=months.get(key)||{total:0,confirmed:0,returned:0,cancelled:0,sum:0};m.total++;if(r.status in m)m[r.status]++;if(['confirmed','returned'].includes(r.status))m.sum+=Number(r.total)||0;months.set(key,m);}$('#statistics-rows').innerHTML=[...months.entries()].sort(([a],[b])=>b.localeCompare(a)).map(([month,m])=>`<tr><td>${e(month)}</td><td>${m.total}</td><td>${m.confirmed}</td><td>${m.returned}</td><td>${m.cancelled}</td><td>${money(m.sum)}</td></tr>`).join('')||'<tr><td colspan="6">Заявок пока нет.</td></tr>';}
const $=s=>document.querySelector(s),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('ru-RU').format(n||0),date=x=>new Date(x).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'});
const labels={pending:'Новая',review:'На проверке',confirmed:'Подтверждена',returned:'Завершена',cancelled:'Отменена'};let token='',base='',rows=[];
$('#api-url').value=window.RENTAL_CONFIG?.apiBase||(['127.0.0.1','localhost'].includes(location.hostname)?'http://127.0.0.1:3000':'');
function notice(text,error=false){$('#admin-notice').textContent=text;$('#admin-notice').classList.toggle('error',error);}
function view(name){document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==name);document.querySelectorAll('aside [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#page-title').textContent={overview:'Обзор и статистика',bookings:'Заявки и аренды',clients:'Клиенты',connection:'Бот и подключение'}[name];}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
async function request(path,opts={}){if(!base)throw Error('Не настроен адрес сервера.');const r=await fetch(base+path,{...opts,credentials:'include',headers:{...(token?{Authorization:'Bearer '+token}:{}),...opts.headers},cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok){let text='Ошибка сервера: '+r.status;try{text=(await r.json()).error||text;}catch{}if(r.status===401)text='Пароль не принят.';const error=Error(text);error.status=r.status;throw error;}return r;}
async function refresh(){try{rows=await request('/admin/bookings').then(r=>r.json());render();renderAnalytics();notice('Данные обновлены.');}catch(error){if(error.status===401){rows=[];token='';document.body.classList.add('is-locked');$('#login-panel').hidden=false;$('#logout').hidden=true;}notice(error.message,true);}}

function render(){renderStatistics();const search=$('#search').value.toLowerCase(),status=$('#status-filter').value;$('#booking-rows').innerHTML=rows.filter(r=>(status==='all'||r.status===status)&&[r.id,r.car,r.client?.name,r.client?.phone].join(' ').toLowerCase().includes(search)).map(r=>`<tr><td><strong>${e(r.client?.name||'Новая заявка')}</strong><small>${e(r.client?.phone||'')}</small><small>${e(r.id.slice(0,10))}</small></td><td>${e(r.car)}</td><td>${date(r.start)}</td><td>${date(r.end)}</td><td>${r.total===null?'Договорная':money(r.total)+' ₽'}</td><td><span class="badge status-${e(r.status)}">${labels[r.status]||e(r.status)}</span></td><td>${(r.status==='review'||(r.status==='pending'&&r.demo_contract))?`<button data-action="confirm" data-id="${e(r.id)}">Подтвердить</button>`:''}${r.status==='confirmed'?`<button data-action="returned" data-id="${e(r.id)}">Возврат авто</button>`:''}${['pending','review','confirmed'].includes(r.status)?`<button data-action="cancelled" data-id="${e(r.id)}">Отменить</button>`:''}${r.telegram_linked?`<button data-action="reply" data-id="${e(r.id)}">Написать в Telegram</button>`:''}${r.telegram_linked?`<button data-action="messages" data-id="${e(r.id)}">Переписка (${Number(r.message_count)||0})</button>`:''}${r.has_documents||r.demo_contract?`<button data-action="contract" data-id="${e(r.id)}">Договор ×2</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">По выбранным условиям заявок нет.</td></tr>';const clients=new Map();for(const r of rows){if(!r.client?.name)continue;const key=r.client.name+'|'+r.client.phone,c=clients.get(key)||{...r.client,count:0};c.count++;clients.set(key,c);}$('#client-rows').innerHTML=[...clients.values()].map(c=>`<tr><td>${e(c.name)}</td><td>${e(c.phone)}</td><td>${c.count}</td></tr>`).join('')||'<tr><td colspan="3">Клиентов с документами пока нет.</td></tr>';document.querySelectorAll('#booking-rows tr').forEach(row=>[...row.children].forEach((cell,index)=>{if(!cell.hasAttribute('colspan'))cell.dataset.label=['Клиент','Автомобиль','Получение · МСК','Возврат · МСК','Стоимость','Статус','Действия'][index];}));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b));}
async function download(path,name){const r=await request(path),blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function action(button){button.disabled=true;try{const id=button.dataset.id,kind=button.dataset.action;if(kind==='messages'){await conversation(id);return;}if(kind==='reply'){const text=prompt('Сообщение клиенту в Telegram:');if(!text?.trim())return;await request('/admin/reply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,text})});notice('Сообщение доставлено в Telegram клиента.');return;}if(kind==='contract'){await download('/admin/contract/'+encodeURIComponent(id),'dogovor-'+id.slice(0,8)+'-2-copies.html');return;}if(!confirm(kind==='confirm'?'Подтвердить заявку? В учебном режиме документы не требуются.':kind==='returned'?'Подтвердить фактический возврат автомобиля?':'Отменить выбранную заявку?'))return;await request(kind==='confirm'?'/admin/confirm':'/admin/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status:kind})});await refresh();}catch(err){notice(err.message,true);}finally{button.disabled=false;}}
$('#login-form').onsubmit=async ev=>{ev.preventDefault();try{const u=new URL($('#api-url').value);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Для удаленного сервера используйте HTTPS.');base=u.origin;token=$('#admin-key').value.trim();const session=await request('/admin/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:token})}).then(r=>r.json());token=session.session_token||'';if(token)sessionStorage.setItem('faeton-session:'+base,token);await request('/admin/bookings');$('#admin-key').value='';$('#login-panel').hidden=true;$('#logout').hidden=false;document.body.classList.remove('is-locked');await refresh();}catch(err){token='';notice(err instanceof TypeError?'Не удалось подключиться. Попробуйте ещё раз.':err.message||'Не удалось подключиться.',true);}};
$('#logout').onclick=async()=>{try{await request('/admin/logout',{method:'POST'});}catch(err){notice('Не удалось завершить серверную сессию. Проверьте соединение и нажмите «Выйти» повторно.',true);return;}sessionStorage.removeItem('faeton-session:'+base);token='';rows=[];$('#statistics-rows').innerHTML='<tr><td colspan="6">Выполнен выход. Войдите повторно для просмотра статистики.</td></tr>';$('#login-panel').hidden=false;$('#logout').hidden=true;document.body.classList.add('is-locked');$('#booking-rows').innerHTML='<tr><td colspan="7">Выполнен выход.</td></tr>';$('#client-rows').innerHTML='<tr><td colspan="3">Выполнен выход.</td></tr>';['#stat-all','#stat-clients','#stat-active','#stat-total'].forEach(s=>$(s).textContent='—');$('#model-chart').textContent='Нет соединения.';$('#status-chart').textContent='Нет соединения.';$('#upcoming').textContent='Нет соединения.';notice('Вы вышли. Сессия завершена на сервере.');};$('#refresh').onclick=refresh;$('#search').oninput=render;$('#status-filter').onchange=render;document.querySelectorAll('[data-export-excel]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await download('/admin/report.xlsx','faeton-kmv-statistics-'+new Date().toISOString().slice(0,10)+'.xlsx');notice('Excel сохранён в загрузки браузера.');}catch(err){notice(err.message,true);}finally{button.disabled=false;}});
view('overview');

async function restoreAdminSession(){const configured=$('#api-url').value;if(!configured)return;try{base=new URL(configured).origin;token=sessionStorage.getItem('faeton-session:'+base)||'';await request('/admin/bookings');$('#login-panel').hidden=true;$('#logout').hidden=false;document.body.classList.remove('is-locked');await refresh();}catch(err){token='';notice(err.status===401?'Введите пароль для входа.':'Сервис временно недоступен. Попробуйте ещё раз.',err.status!==401);}}
restoreAdminSession();

async function conversation(id){const dialog=document.createElement('dialog');dialog.className='conversation-dialog';dialog.innerHTML='<button type="button" class="close-conversation">Закрыть ×</button><h2>Переписка по заявке</h2><div class="messages"></div><form><label>Ответ клиенту<textarea required maxlength="3000" rows="4"></textarea></label><button>Отправить в Telegram</button></form><p role="status"></p>';document.body.append(dialog);dialog.querySelector('.close-conversation').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());const status=dialog.querySelector('[role="status"]');async function load(){const messages=await request('/admin/messages?id='+encodeURIComponent(id)).then(r=>r.json());dialog.querySelector('.messages').innerHTML=messages.map(m=>`<article><strong>${m.author==='client'?'Клиент':'Менеджер'}</strong><small>${date(m.created_at)}</small><p>${e(m.body)}</p></article>`).join('')||'<p>Сообщений пока нет. Клиент может написать через кнопку «Написать менеджеру» в боте.</p>';}dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button'),input=dialog.querySelector('textarea');button.disabled=true;try{await request('/admin/reply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,text:input.value})});input.value='';status.textContent='Ответ отправлен в Telegram.';await load();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};dialog.showModal();try{await load();}catch(error){status.textContent=error.message;}}

function analyticsRows(){const period=$('#analytics-period')?.value||'all',now=new Date(),msk=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(d),today=msk(now);return rows.filter(row=>{const day=msk(new Date(row.start));if(period==='month')return day.slice(0,7)===today.slice(0,7);if(period==='next30')return day>=today&&day<=msk(new Date(+now+30*86400000));if(period==='last30')return day<=today&&day>=msk(new Date(+now-29*86400000));return true;});}
function renderAnalytics(){const data=analyticsRows(),now=Date.now();$('#stat-all').textContent=money(data.length);$('#stat-clients').textContent=money(data.filter(r=>['pending','review'].includes(r.status)).length);$('#stat-active').textContent=money(data.filter(r=>r.status==='confirmed'&&Date.parse(r.start)<=now&&Date.parse(r.end)>now).length);$('#stat-total').textContent=money(data.filter(r=>['confirmed','returned'].includes(r.status)).reduce((sum,r)=>sum+(Number(r.total)||0),0));const models=new Map();for(const row of data)models.set(row.car,(models.get(row.car)||0)+1);const list=[...models].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...list.map(x=>x[1]));$('#model-chart').innerHTML=list.map(([name,n])=>'<div class="chart-row"><span>'+e(name)+'</span><div class="chart-bar"><i style="width:'+Math.round(n/max*100)+'%"></i></div><b>'+n+'</b></div>').join('')||'<p>В этом периоде заявок нет.</p>';$('#status-chart').innerHTML=Object.entries(labels).map(([key,label])=>'<div><span>'+label+'</span><strong>'+data.filter(r=>r.status===key).length+'</strong></div>').join('');$('#upcoming').innerHTML=data.filter(r=>r.status==='confirmed'&&Date.parse(r.end)>now).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,8).map(r=>'<div><strong>'+e(r.car)+'</strong><span>'+date(r.start)+' → '+date(r.end)+'</span><span>'+e(r.client?.name||'Клиент')+'</span></div>').join('')||'<p>Подтверждённых выдач и возвратов в этом периоде нет.</p>';renderStatistics();}
$('#analytics-period').onchange=renderAnalytics;
